styles:
body { margin: 0; }
    a { color: #6b521f; text-decoration: underline; text-decoration-color: rgba(138,109,59,0.35); }
    a:hover { color: #5c4826; }
    ::selection { background: rgba(138,109,59,0.25); }

logic:
class Component extends DCLogic {
  state = {
    zoomIndex: null,
    scale: 1,
    offsetX: 0,
    offsetY: 0,
    dragging: false,
    dragStartX: 0,
    dragStartY: 0,
    dragOffsetStartX: 0,
    dragOffsetStartY: 0
  };

  noteData = [
    {
      key: "1994-embera",
      label: "Diez Mil Pesos \u00b7 15 de octubre de 1994",
      denomination: "Diez Mil Pesos",
      date: "15 de octubre de 1994",
      obverse: "Retrato de una mujer del pueblo emberá a la derecha, junto a una figura de orfebrería quimbaya y dos embarcaciones que representan la llegada de los conquistadores. Emitido para conmemorar el quinto centenario del 12 de octubre de 1492. Sobreimpresión roja \u201cMUESTRA SIN VALOR\u201d. Numeración en ceros.",
      reverse: "Aves representativas de Colombia \u2014flamenco, cóndor andino, gallito de las rocas, guacamaya bandera, pelícano, tucán y loro amazónico, entre otras\u2014 enmarcando el mapamundi de Martin Waldseemüller de 1507, el primer documento cartográfico en usar el nombre \u201cAmérica\u201d.",
      condition: "Gema sin circular, con perforaciones de cancelación características. Colores vivos y muy bien conservados.",
      pick: "Pick P-440 (variante conmemorativa)",
      description: "Primer billete colombiano de Diez Mil Pesos, emitido en 1992 para conmemorar el quinto centenario de la llegada de los españoles a América, con diseño ganador de un concurso de la pintora bogotana Liliana Ponce de León. Fue también el primer billete del país en llevar en su anverso a una mujer indígena en lugar de un prócer.",
      jpg: "uploads/colombia-banco-de-la-republica-10000-pesos-1994-embera-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-10000-pesos-1994-embera-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-10000-pesos-1994-embera-specimen.webp",
      alt: "Billete especimen de Diez Mil Pesos de El Banco de la República, Colombia, fechado 15 de octubre de 1994, con el retrato de una mujer emberá y un collage de biodiversidad en el reverso"
    },
    {
      key: "1995-la-pola",
      label: "Diez Mil Pesos \u00b7 1 de marzo de 1995",
      denomination: "Diez Mil Pesos",
      date: "1 de marzo de 1995",
      obverse: "Retrato de Policarpa Salavarrieta, &ldquo;La Pola&rdquo;, basado en el óleo de 1855 del pintor José María Espinosa, en la colección del Museo Nacional. Sobreimpresión roja \u201cMUESTRA SIN VALOR\u201d. Numeración en ceros. Firmas de Gerente General y Gerente Ejecutivo.",
      reverse: "Perspectiva del municipio de Guaduas, tomada de la acuarela &ldquo;Escena de mercado&rdquo; (1846) del pintor y diplomático inglés Edward Walhouse Mark. Texto: \u201cDIEZ MIL PESOS\u201d.",
      condition: "Gema sin circular, con perforaciones de cancelación características.",
      pick: "Pick P-441 (variante por fecha)",
      description: "Espécimen del nuevo diseño en homenaje a Policarpa Salavarrieta, puesto en circulación el 30 de noviembre de 1995 junto con la edición del 1 de julio del mismo año, con una vista de Guaduas en el reverso, en contraste con el diseño conmemorativo de la mujer emberá que reemplazó.",
      jpg: "uploads/colombia-banco-de-la-republica-10000-pesos-1995-la-pola-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-10000-pesos-1995-la-pola-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-10000-pesos-1995-la-pola-specimen.webp",
      alt: "Billete especimen de Diez Mil Pesos de El Banco de la República, Colombia, fechado 1 de marzo de 1995, con el retrato de Policarpa Salavarrieta y una escena rural en el reverso"
    }
  ];

  focusClose = () => {
    const closeBtn = document.querySelector('[data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusClose);
  };

  openZoomAt = (index) => {
    this.setState({ zoomIndex: index, scale: 1, offsetX: 0, offsetY: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose));
  };

  closeZoom = () => {
    this.setState({ zoomIndex: null });
  };

  stopPropagation = (e) => e.stopPropagation();

  zoomIn = () => {
    this.setState(s => ({ scale: Math.min(4, Math.round((s.scale + 0.5) * 10) / 10) }));
  };

  zoomOut = () => {
    this.setState(s => {
      const next = Math.max(1, Math.round((s.scale - 0.5) * 10) / 10);
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale + delta) * 100) / 100));
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onPointerDown = (e) => {
    if (this.state.scale <= 1) return;
    this.setState({
      dragging: true,
      dragStartX: e.clientX,
      dragStartY: e.clientY,
      dragOffsetStartX: this.state.offsetX,
      dragOffsetStartY: this.state.offsetY
    });
  };

  onPointerMove = (e) => {
    if (!this.state.dragging) return;
    const dx = e.clientX - this.state.dragStartX;
    const dy = e.clientY - this.state.dragStartY;
    this.setState({ offsetX: this.state.dragOffsetStartX + dx, offsetY: this.state.dragOffsetStartY + dy });
  };

  onPointerUp = () => this.setState({ dragging: false });

  onKeyDown = (e) => {
    if (e.key === "Escape" && this.state.zoomIndex !== null) this.closeZoom();
  };

  componentDidMount() {
    document.addEventListener("keydown", this.onKeyDown);
    if (typeof document !== "undefined" && document.documentElement) {
      document.documentElement.lang = "es";
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.onKeyDown);
  }

  renderVals() {
    const s = this.state;
    const notes = this.noteData.map((n, i) => Object.assign({}, n, { openZoom: () => this.openZoomAt(i) }));
    const active = s.zoomIndex !== null ? this.noteData[s.zoomIndex] : null;

    return {
      notes,
      zoomIndex: s.zoomIndex !== null,
      closeZoom: this.closeZoom,
      stopPropagation: this.stopPropagation,
      zoomInHandler: this.zoomIn,
      zoomOutHandler: this.zoomOut,
      onWheel: this.onWheel,
      onPointerDown: this.onPointerDown,
      onPointerMove: this.onPointerMove,
      onPointerUp: this.onPointerUp,
      zoomInDisabled: s.scale >= 4,
      zoomOutDisabled: s.scale <= 1,
      zoomPercent: Math.round(s.scale * 100) + "%",
      imgTransform: `translate(${s.offsetX}px, ${s.offsetY}px) scale(${s.scale})`,
      imgCursor: s.scale > 1 ? (s.dragging ? "grabbing" : "grab") : "default",
      activeNoteJpg: active ? active.jpg : "",
      activeNoteWebp: active ? active.webp : ""
    };
  }
}
